type config struct {
	input string
	inputSet bool
	output string
	outputSet bool
	outputOverwrite bool
	domain string
	excludeSelectors []string
	includeSelectors []string
	strongDelimiter string
	tableCellPadding string
	tableHeaderPromotion bool
	tableHeaderPromotionSet bool
	tableNewlineBehavior string
	tablePresentation bool
	tablePresentationSet bool
	tableSkipEmptyRows bool
	tableSkipEmptyRowsSet bool
	tableSpanBehavior string
	pluginStrikethrough bool
	pluginTable bool
	version bool
}

func parseFlags(args []string) (*config, []string, bool, string) {
	cfg := &config{}
	var posArgs []string
	endOfFlags := false
	i := 0
	for i < len(args) {
		arg := args[i]
		if endOfFlags {
			posArgs = append(posArgs, arg)
			i++
			continue
		}
		if arg == "--" {
			endOfFlags = true
			i++
			continue
		}
		if len(arg) >= 1 && arg[0] == '-' && len(arg) > 1 {
			// Flag
			name, value, hasValue := splitFlag(arg)
			// Normalize name: strip leading dashes (one or two)
			norm := strings.TrimLeft(name, "-")
			// Actually name includes dashes? splitFlag returns name with dashes? Let's define splitFlag to return name without value part, with dashes.
			// Then norm is without dashes.
			// Handle help aliases: h, help
			if norm == "h" || norm == "help" {
				// Immediate help, ignore value and remaining
				return cfg, nil, true, ""
			}
			// Handle version aliases: v, version
			if norm == "v" || norm == "version" {
				if hasValue {
					b, err := strconv.ParseBool(value)
					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
					cfg.version = b
				} else {
					cfg.version = true
				}
				i++
				continue
			}
			// Bool flags (no arg, optional =value, never consume next)
			switch norm {
			case "plugin-table":
				if hasValue {
					b, err := strconv.ParseBool(value)
					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
					cfg.pluginTable = b
				} else {
					cfg.pluginTable = true
				}
				i++
				continue
			case "plugin-strikethrough":
				if hasValue {
					b, err := strconv.ParseBool(value)
					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
