					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
					cfg.tablePresentation = b
					cfg.tablePresentationSet = true
				} else {
					cfg.tablePresentation = true
					cfg.tablePresentationSet = true
				}
				i++
				continue
			case "opt-table-skip-empty-rows":
