				if hasValue {
					val = value
				} else {
					if i+1 >= len(args) {
						return nil, nil, false, fmt.Sprintf("flag needs an argument: -%s", norm)
					}
					val = args[i+1]
					i++ // consume next
				}
				// Validate/store
				switch norm {
				case "input":
					if cfg.inputSet {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: another value has already been set", val, norm)
					}
					if val == "" {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: empty string", val, norm)
					}
					cfg.input = val
					cfg.inputSet = true
				case "output":
					if cfg.outputSet {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: another value has already been set", val, norm)
					}
					if val == "" {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: empty string", val, norm)
					}
					cfg.output = val
					cfg.outputSet = true
				case "domain":
					cfg.domain = val
				case "exclude-selector":
					if errStr := validateSelector(val); errStr != "" {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: %s", val, norm, errStr)
					}
					cfg.excludeSelectors = append(cfg.excludeSelectors, val)
				case "include-selector":
					if errStr := validateSelector(val); errStr != "" {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: %s", val, norm, errStr)
					}
					cfg.includeSelectors = append(cfg.includeSelectors, val)
				case "opt-strong-delimiter":
					cfg.strongDelimiter = val
				case "opt-table-cell-padding-behavior":
					cfg.tableCellPadding = val
				case "opt-table-newline-behavior":
					cfg.tableNewlineBehavior = val
				case "opt-table-span-cell-behavior":
					cfg.tableSpanBehavior = val
				}
				i++
				continue
			default:
				// Unknown flag
				display := formatFlagDisplay(norm)
				msg := fmt.Sprintf("unknown flag: %s", display)
				if sug := suggestFlag(norm); sug != "" {
					msg += fmt.Sprintf("\n\nDid you mean %s instead?", sug)
				}
				return nil, nil, false, msg
			}
		} else {
			// Positional: from here, all remaining are positional (flag parsing stops)
			posArgs = append(posArgs, arg)
			// Append remaining args as positional too (including flags after positional)
			for j := i + 1; j < len(args); j++ {
				posArgs = append(posArgs, args[j])
			}
			break
		}
	}
	return cfg, posArgs, false, ""
}

func splitFlag(arg string) (name, value string, hasValue bool) {
	if idx := strings.Index(arg, "="); idx != -1 {
		return arg[:idx], arg[idx+1:], true
	}
	return arg, "", false
}

func formatFlagDisplay(norm string) string {
	if len(norm) == 1 {
		return "-" + norm
	}
	return "--" + norm
}

func suggestFlag(unknown string) string {
	// Known flags for suggestion (excluding help/h)
	known := []string{"input", "output", "output-overwrite", "domain", "exclude-selector", "include-selector", "opt-strong-delimiter", "opt-table-cell-padding-behavior", "opt-table-header-promotion", "opt-table-newline-behavior", "opt-table-presentation-tables", "opt-table-skip-empty-rows", "opt-table-span-cell-behavior", "plugin-strikethrough", "plugin-table", "version", "v"}
	best := ""
	bestDist := -1
	for _, k := range known {
		d := levenshtein(unknown, k)
		if bestDist == -1 || d < bestDist || (d == bestDist && len(k) < len(strings.TrimPrefix(best, "--")) && len(k) < len(strings.TrimPrefix(best, "-"))) {
			// Tie-breaking: shorter known flag wins? Need to handle display prefix.
			// Actually compare len(k) directly.
			if d == bestDist {
				// Tie: pick shorter k, then alphabetical?
				bestNorm := strings.TrimPrefix(strings.TrimPrefix(best, "--"), "-")
				if len(k) < len(bestNorm) || (len(k) == len(bestNorm) && k < bestNorm) {
					bestDist = d
					best = k
				}
			} else {
				bestDist = d
				best = k
			}
		}
	}
	if best == "" {
		return ""
	}
	// Threshold: min(4, len(unknown)-1), len>=1? For len1, threshold 0, so distance>=1 never suggests. Good.
	thresh := 4
	if len(unknown)-1 < thresh {
		thresh = len(unknown) - 1
	}
	if thresh < 0 {
		thresh = 0
	}
	if bestDist > thresh {
		return ""
	}
	return formatFlagDisplay(best)
}

func levenshtein(a, b string) int {
	m, n := len(a), len(b)
	if m == 0 {
		return n
	}
	if n == 0 {
		return m
	}
	prev := make([]int, n+1)
	cur := make([]int, n+1)
	for j := 0; j <= n; j++ {
		prev[j] = j
	}
	for i := 1; i <= m; i++ {
		cur[0] = i
		for j := 1; j <= n; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		prev, cur = cur, prev
	}
	return prev[n]
}

func min3(a, b, c int) int {
	if a < b {
		if a < c {
			return a
		}
		return c
	}
	if b < c {
		return b
	}
	return c
}

func checkTableRequires(cfg *config) string {
	if cfg.pluginTable {
		return ""
	}
	// Order: skip, header, span, presentation, newline, cell
	if cfg.tableSkipEmptyRowsSet {
		return "--opt-table-skip-empty-rows requires --plugin-table to be enabled"
	}
	if cfg.tableHeaderPromotionSet {
		return "--opt-table-header-promotion requires --plugin-table to be enabled"
	}
	if cfg.tableSpanBehavior != "" {
		return "--opt-table-span-cell-behavior requires --plugin-table to be enabled"
	}
	if cfg.tablePresentationSet {
		return "--opt-table-presentation-tables requires --plugin-table to be enabled"
	}
	if cfg.tableNewlineBehavior != "" {
		return "--opt-table-newline-behavior requires --plugin-table to be enabled"
	}
	if cfg.tableCellPadding != "" {
		return "--opt-table-cell-padding-behavior requires --plugin-table to be enabled"
	}
	return ""
}

func cleanMkdirPath(output string, isDir bool) string {
	if isDir {
		return strings.TrimSuffix(output, "/")
	}
	return output
}

func extractOSError(err error) string {
	// os.MkdirAll error is *PathError with Op, Path, Err. We want Err.Error()? e.g., "not a directory", "no such file or directory", "permission denied", "file exists"?
	// err.Error() is like "mkdir /tmp/...: not a directory". We want only last part after ": "? Actually our format is "mkdir %s: %s" where %s is path and %s is os error string.
	// If err is PathError, Err.Error() is "not a directory", etc.
	// Use type assertion? Simpler: if err.Error() contains ": ", take last part? But path may contain ": "? Unlikely.
	// Better to use errors.As with *os.PathError and *os.LinkError etc.
	if pe, ok := err.(*os.PathError); ok {
		return pe.Err.Error()
	}
	if le, ok := err.(*os.LinkError); ok {
		return le.Err.Error()
	}
	// Fallback: try to extract after last ": "
	s := err.Error()
	if idx := strings.LastIndex(s, ": "); idx != -1 {
		return s[idx+2:]
	}
	return s
}

