				return cfg, nil, true, ""
			}
			// Handle version aliases: v, version
			if norm == "v" || norm == "version" {
				if hasValue {
					b, err := strconv.ParseBool(value)
					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
					cfg.version = b
				} else {
					cfg.version = true
				}
				i++
				continue
			}
			// Bool flags (no arg, optional =value, never consume next)
			switch norm {
			case "plugin-table":
				if hasValue {
					b, err := strconv.ParseBool(value)
					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
					cfg.pluginTable = b
				} else {
					cfg.pluginTable = true
				}
				i++
				continue
			case "plugin-strikethrough":
				if hasValue {
					b, err := strconv.ParseBool(value)
					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
					cfg.pluginStrikethrough = b
				} else {
					cfg.pluginStrikethrough = true
				}
				i++
				continue
			case "output-overwrite":
				if hasValue {
					b, err := strconv.ParseBool(value)
					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
					cfg.outputOverwrite = b
				} else {
					cfg.outputOverwrite = true
				}
				i++
				continue
			case "opt-table-header-promotion":
				if hasValue {
					b, err := strconv.ParseBool(value)
					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
					cfg.tableHeaderPromotion = b
					cfg.tableHeaderPromotionSet = true
				} else {
					cfg.tableHeaderPromotion = true
					cfg.tableHeaderPromotionSet = true
				}
				i++
				continue
			case "opt-table-presentation-tables":
				if hasValue {
					b, err := strconv.ParseBool(value)
					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
					cfg.tablePresentation = b
					cfg.tablePresentationSet = true
				} else {
					cfg.tablePresentation = true
					cfg.tablePresentationSet = true
				}
				i++
				continue
			case "opt-table-skip-empty-rows":
				if hasValue {
					b, err := strconv.ParseBool(value)
					if err != nil {
						return nil, nil, false, fmt.Sprintf("invalid boolean value %q for -%s: parse error", value, norm)
					}
					cfg.tableSkipEmptyRows = b
					cfg.tableSkipEmptyRowsSet = true
				} else {
					cfg.tableSkipEmptyRows = true
					cfg.tableSkipEmptyRowsSet = true
				}
				i++
				continue
			}
			// String flags (require arg, via = or next)
			switch norm {
			case "input", "output", "domain", "exclude-selector", "include-selector", "opt-strong-delimiter", "opt-table-cell-padding-behavior", "opt-table-newline-behavior", "opt-table-span-cell-behavior":
				var val string
				if hasValue {
					val = value
				} else {
					if i+1 >= len(args) {
						return nil, nil, false, fmt.Sprintf("flag needs an argument: -%s", norm)
					}
					val = args[i+1]
					i++ // consume next
				}
				// Validate/store
				switch norm {
				case "input":
					if cfg.inputSet {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: another value has already been set", val, norm)
					}
					if val == "" {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: empty string", val, norm)
					}
					cfg.input = val
					cfg.inputSet = true
				case "output":
					if cfg.outputSet {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: another value has already been set", val, norm)
					}
					if val == "" {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: empty string", val, norm)
					}
					cfg.output = val
					cfg.outputSet = true
				case "domain":
					cfg.domain = val
				case "exclude-selector":
					if errStr := validateSelector(val); errStr != "" {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: %s", val, norm, errStr)
					}
					cfg.excludeSelectors = append(cfg.excludeSelectors, val)
				case "include-selector":
					if errStr := validateSelector(val); errStr != "" {
						return nil, nil, false, fmt.Sprintf("invalid value %q for flag -%s: %s", val, norm, errStr)
					}
					cfg.includeSelectors = append(cfg.includeSelectors, val)
				case "opt-strong-delimiter":
					cfg.strongDelimiter = val
				case "opt-table-cell-padding-behavior":
					cfg.tableCellPadding = val
				case "opt-table-newline-behavior":
					cfg.tableNewlineBehavior = val
				case "opt-table-span-cell-behavior":
					cfg.tableSpanBehavior = val
				}
				i++
				continue
			default:
				// Unknown flag
				display := formatFlagDisplay(norm)
				msg := fmt.Sprintf("unknown flag: %s", display)
				if sug := suggestFlag(norm); sug != "" {
					msg += fmt.Sprintf("\n\nDid you mean %s instead?", sug)
