		} else {
			// Positional: from here, all remaining are positional (flag parsing stops)
			posArgs = append(posArgs, arg)
			// Append remaining args as positional too (including flags after positional)
			for j := i + 1; j < len(args); j++ {
				posArgs = append(posArgs, args[j])
			}
			break
		}
	}
	return cfg, posArgs, false, ""
}

func splitFlag(arg string) (name, value string, hasValue bool) {
	if idx := strings.Index(arg, "="); idx != -1 {
		return arg[:idx], arg[idx+1:], true
	}
	return arg, "", false
}

func formatFlagDisplay(norm string) string {
	if len(norm) == 1 {
