// Matching logic

func matchesSelector(node *html.Node, sel *Selector) bool {
	// Match complex selector from rightmost part to leftmost (right-to-left)
	if len(sel.parts) == 0 {
		return false
	}
	return matchFrom(node, sel, len(sel.parts)-1)
}

func matchFrom(node *html.Node, sel *Selector, idx int) bool {
	if idx < 0 {
		return true
	}
	part := sel.parts[idx]
	if !matchesCompound(node, part.compound) {
		return false
	}
	if idx == 0 {
		return true
	}
	comb := part.combinator
	// combinator is between idx-1 and idx (stored in part idx? Actually part.combinator is combinator to previous part. For first part, combinator "". Good.
	// For idx>0, comb is part.combinator (e.g., " ", ">", "+", "~")
	prevIdx := idx - 1
	switch comb {
	case " ":
		// Descendant: any ancestor matches prev
		for p := node.Parent; p != nil; p = p.Parent {
			if p.Type != html.ElementNode {
				continue
			}
			if matchFrom(p, sel, prevIdx) {
				return true
			}
			// Continue up? Actually matchFrom checks prev part and further left. For descendant, need to try each ancestor as potential prev match.
			// Our recursion tries p as prev, and if prev matches (including its left context), return true. Else try next ancestor.
			// But matchFrom(p, sel, prevIdx) already checks p matches prev compound and recursively checks left. Good.
		}
		return false
	case ">":
		// Child: parent must match prev
		p := node.Parent
		// Skip non-element parents? In HTML, parent is always element (except document). Good.
		for p != nil && p.Type != html.ElementNode {
			p = p.Parent
		}
		if p == nil {
			return false
		}
		return matchFrom(p, sel, prevIdx)
	case "+":
		// Adjacent sibling: previous element sibling must match prev
		prev := previousElementSibling(node)
		if prev == nil {
			return false
		}
		return matchFrom(prev, sel, prevIdx)
	case "~":
		// General sibling: any previous element sibling matches prev
		for sib := previousElementSibling(node); sib != nil; sib = previousElementSibling(sib) {
			if matchFrom(sib, sel, prevIdx) {
				return true
			}
		}
		return false
	default:
		// No combinator? Should not happen for idx>0 (first part has "", others should have combinator). If comb=="" for idx>0, treat as descendant? Or error? For safety, treat as descendant.
		for p := node.Parent; p != nil; p = p.Parent {
			if p.Type != html.ElementNode {
				continue
			}
			if matchFrom(p, sel, prevIdx) {
				return true
			}
		}
		return false
	}
}

func previousElementSibling(n *html.Node) *html.Node {
	for sib := n.PrevSibling; sib != nil; sib = sib.PrevSibling {
		if sib.Type == html.ElementNode {
			return sib
		}
	}
	return nil
}

func matchesCompound(node *html.Node, c *Compound) bool {
	if node.Type != html.ElementNode {
		return false
	}
	// Type
	if c.typeSel != "" && c.typeSel != "*" {
		if !strings.EqualFold(node.Data, c.typeSel) {
			return false
		}
	}
	// ID
	if c.id != "" {
		idVal := getAttr(node, "id")
		if idVal != c.id {
			return false
		}
	}
	// Classes
	if len(c.classes) > 0 {
		classVal := getAttr(node, "class")
		classes := strings.Fields(classVal)
		classSet := make(map[string]bool)
		for _, cl := range classes {
			classSet[cl] = true
		}
		for _, need := range c.classes {
			if !classSet[need] {
				return false
			}
		}
	}
	// Attrs
	for _, a := range c.attrs {
		if !matchesAttr(node, &a) {
			return false
		}
	}
	// Pseudos
	for _, p := range c.pseudos {
		if !matchesPseudo(node, &p) {
			return false
		}
	}
	return true
}

func getAttr(n *html.Node, name string) string {
	for _, a := range n.Attr {
		if strings.EqualFold(a.Key, name) {
			return a.Val
		}
	}
	return ""
}

func hasAttr(n *html.Node, name string) bool {
	for _, a := range n.Attr {
		if strings.EqualFold(a.Key, name) {
			return true
		}
	}
	return false
}

func matchesAttr(node *html.Node, a *AttrSel) bool {
	val, ok := func() (string, bool) {
		for _, at := range node.Attr {
			if strings.EqualFold(at.Key, a.name) {
				return at.Val, true
			}
		}
		return "", false
	}()
	if a.op == "" {
		return ok
	}
	if !ok {
		return false
	}
	target := a.value
	// Case handling: if caseInsensitive, compare lowercased
	if a.caseInsensitive {
		val = strings.ToLower(val)
		target = strings.ToLower(target)
	}
	switch a.op {
	case "=":
		return val == target
	case "~=":
		// Whitespace-separated list contains target
		for _, f := range strings.Fields(val) {
			if f == target {
				return true
			}
		}
		return false
	case "|=":
		// Exactly target or target-*
		return val == target || strings.HasPrefix(val, target+"-")
	case "^=":
		return strings.HasPrefix(val, target)
	case "$=":
		return strings.HasSuffix(val, target)
	case "*=":
		return strings.Contains(val, target)
	default:
		return false
	}
}

func matchesPseudo(node *html.Node, p *PseudoSel) bool {
	switch p.name {
