func isFirstChild(n *html.Node) bool {
	if n.Parent == nil {
		return false
	}
	for sib := n.Parent.FirstChild; sib != nil; sib = sib.NextSibling {
		if sib.Type == html.ElementNode {
			return sib == n
		}
	}
	return false
}

func isLastChild(n *html.Node) bool {
	if n.Parent == nil {
		return false
	}
	for sib := n.Parent.LastChild; sib != nil; sib = sib.PrevSibling {
		if sib.Type == html.ElementNode {
			return sib == n
		}
	}
	return false
}

func isFirstOfType(n *html.Node) bool {
	if n.Parent == nil {
		return false
	}
	tag := strings.ToLower(n.Data)
	for sib := n.Parent.FirstChild; sib != nil; sib = sib.NextSibling {
		if sib.Type == html.ElementNode && strings.ToLower(sib.Data) == tag {
			return sib == n
		}
	}
	return false
}

func isLastOfType(n *html.Node) bool {
	if n.Parent == nil {
		return false
	}
	tag := strings.ToLower(n.Data)
	for sib := n.Parent.LastChild; sib != nil; sib = sib.PrevSibling {
		if sib.Type == html.ElementNode && strings.ToLower(sib.Data) == tag {
			return sib == n
		}
	}
	return false
}

func isEmpty(n *html.Node) bool {
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		if c.Type == html.ElementNode {
			return false
		}
		if c.Type == html.TextNode {
			// Even whitespace text counts as not empty? In CSS, :empty matches only if no children at all (including text). Whitespace text is child, so not empty.
			// What about empty text ""? Unlikely. Any text node (even whitespace) means not empty.
			return false
		}
	}
	return true
}

func matchesNth(n *html.Node, expr string, fromEnd, ofType bool) bool {
	// Compute index (1-based) among siblings (all elements or same type)
	if n.Parent == nil {
		return false
	}
	var siblings []*html.Node
	tag := strings.ToLower(n.Data)
	for sib := n.Parent.FirstChild; sib != nil; sib = sib.NextSibling {
		if sib.Type != html.ElementNode {
			continue
		}
		if ofType && strings.ToLower(sib.Data) != tag {
			continue
		}
		siblings = append(siblings, sib)
	}
	idx := -1
	for i, s := range siblings {
		if s == n {
			idx = i + 1 // 1-based from start
			break
		}
	}
	if idx == -1 {
		return false
	}
	if fromEnd {
		idx = len(siblings) - idx + 1 // 1-based from end
	}
	a, b, ok := parseNth(expr)
	if !ok {
		return false
	}
	return matchesAnB(idx, a, b)
}

func parseNth(expr string) (a, b int, ok bool) {
	s := strings.TrimSpace(expr)
	low := strings.ToLower(s)
	if low == "odd" {
		return 2, 1, true
	}
	if low == "even" {
		return 2, 0, true
	}
