	if idx >= len(t) || (t[idx] != 'n' && t[idx] != 'N') {
		return 0, 0, false
	}
	idx++
	if idx >= len(t) {
		return aVal, 0, true
	}
	// Expect +/-
	signB := 1
	if t[idx] == '+' {
		signB = 1
	} else if t[idx] == '-' {
		signB = -1
	} else {
		return 0, 0, false
	}
	idx++
	if idx >= len(t) {
		return 0, 0, false
	}
