// isDescendant checks if node is descendant of ancestor (strict, not self)
func isDescendant(node, ancestor *html.Node) bool {
	for p := node.Parent; p != nil; p = p.Parent {
		if p == ancestor {
			return true
		}
	}
	return false
}
