func extractLang(n *html.Node) string {
	// Look for class attribute with language-xxx or lang-xxx
	class := getAttr(n, "class")
	if class == "" {
		return ""
	}
	for _, part := range strings.Fields(class) {
		if strings.HasPrefix(part, "language-") {
			lang := strings.TrimPrefix(part, "language-")
			if lang != "" {
				return lang
			}
		} else if strings.HasPrefix(part, "lang-") {
			lang := strings.TrimPrefix(part, "lang-")
			if lang != "" {
				return lang
			}
		}
	}
	return ""
}

func getPreContent(n *html.Node) string {
	// Recursively collect text, preserving whitespace, handling br as \n, ignoring tags (span, etc.) but including their text, handling entities (raw, no escaping)
	var sb strings.Builder
	var dfs func(*html.Node)
	dfs = func(node *html.Node) {
		if node.Type == html.TextNode {
			sb.WriteString(node.Data)
			return
		}
		if node.Type != html.ElementNode {
			return
		}
		tag := strings.ToLower(node.Data)
		if tag == "br" {
			sb.WriteString("\n")
			return
		}
		// For other elements (span, code, etc.), recurse into children (ignore tag itself)
		for c := node.FirstChild; c != nil; c = c.NextSibling {
			dfs(c)
		}
	}
	for c := n.FirstChild; c != nil; c = c.NextSibling {
		dfs(c)
	}
	return sb.String()
}

