	*out = v
	return n, nil
}

func parseIntInternal(s string, out *int) (int, error) {
	if s == "" {
		return 0, fmt.Errorf("empty")
	}
	i := 0
	neg := false
	if s[0] == '+' || s[0] == '-' {
		if s[0] == '-' {
			neg = true
		}
		i++
		if i >= len(s) {
			return 0, fmt.Errorf("invalid")
		}
	}
	if i >= len(s) || s[i] < '0' || s[i] > '9' {
		return 0, fmt.Errorf("invalid")
	}
	v := 0
	for ; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, fmt.Errorf("invalid")
		}
		v = v*10 + int(s[i]-'0')
	}
	if neg {
		v = -v
	}
	*out = v
	return 0, nil
}

func intToString(i int) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var b [20]byte
	pos := len(b)
	for i > 0 {
		pos--
		b[pos] = byte('0' + i%10)
		i /= 10
	}
	if neg {
		pos--
		b[pos] = '-'
	}
	return string(b[pos:])
}
