func (c *Converter) convertInlinesInternal(nodes []*html.Node, ctx inlineContext) string {
	// Handle brs first (unless inCode/inHeading where br as space)
	hasBr := false
	for _, n := range nodes {
		if n.Type == html.ElementNode && strings.EqualFold(n.Data, "br") {
			hasBr = true
			break
		}
	}
	if hasBr && !ctx.inCode && !ctx.inHeading {
		if ctx.inLink {
			// Link text with brs: handle specially (no splitting, keep single string with breaks)
			return c.convertLinkTextWithBreaks(nodes, ctx)
		}
		// General (li, etc.): split by brs like convertInlineContainer
		return c.convertInlinesWithBreaks(nodes, ctx)
	}
	if hasBr && (ctx.inCode || ctx.inHeading) {
		// Replace brs with spaces
		var mapped []*html.Node
		for _, n := range nodes {
			if n.Type == html.ElementNode && strings.EqualFold(n.Data, "br") {
				mapped = append(mapped, &html.Node{Type: html.TextNode, Data: " "})
			} else {
				mapped = append(mapped, n)
			}
		}
		nodes = mapped
	}
	// No brs (or brs replaced), convert with merging
	return c.convertInlinesNoBr(nodes, ctx)
}

