func (c *Converter) convertInlinesInternal(nodes []*html.Node, ctx inlineContext) string {
	// Handle brs first (unless inCode/inHeading where br as space)
	hasBr := false
	for _, n := range nodes {
		if n.Type == html.ElementNode && strings.EqualFold(n.Data, "br") {
			hasBr = true
			break
		}
	}
	if hasBr && !ctx.inCode && !ctx.inHeading {
		if ctx.inLink {
			// Link text with brs: handle specially (no splitting, keep single string with breaks)
			return c.convertLinkTextWithBreaks(nodes, ctx)
		}
		// General (li, etc.): split by brs like convertInlineContainer
		return c.convertInlinesWithBreaks(nodes, ctx)
	}
	if hasBr && (ctx.inCode || ctx.inHeading) {
		// Replace brs with spaces
		var mapped []*html.Node
		for _, n := range nodes {
			if n.Type == html.ElementNode && strings.EqualFold(n.Data, "br") {
				mapped = append(mapped, &html.Node{Type: html.TextNode, Data: " "})
			} else {
				mapped = append(mapped, n)
			}
		}
		nodes = mapped
	}
	// No brs (or brs replaced), convert with merging
	return c.convertInlinesNoBr(nodes, ctx)
}

func (c *Converter) convertInlinesWithBreaks(nodes []*html.Node, ctx inlineContext) string {
	// Split by br groups (like convertInlineContainer), join segments with "  \n" (single) or "\n\n" (double+)
	var segments [][]*html.Node
	var seps []int
	var cur []*html.Node
	i := 0
	for i < len(nodes) {
		ch := nodes[i]
		if ch.Type == html.ElementNode && strings.EqualFold(ch.Data, "br") {
			brCount := 0
			j := i
			for j < len(nodes) {
				nj := nodes[j]
				if nj.Type == html.ElementNode && strings.EqualFold(nj.Data, "br") {
					brCount++
					j++
				} else if nj.Type == html.TextNode && strings.TrimSpace(nj.Data) == "" {
					j++
				} else if nj.Type == html.CommentNode {
					j++
				} else {
					break
				}
			}
			segments = append(segments, cur)
			seps = append(seps, brCount)
			cur = nil
			i = j
		} else {
			cur = append(cur, ch)
			i++
		}
	}
	segments = append(segments, cur)
	var segStrs []string
	for _, seg := range segments {
		s := c.convertInlinesNoBr(seg, ctx)
		segStrs = append(segStrs, strings.TrimSpace(s))
	}
	var nonEmpty []string
	var nonEmptyIdx []int
	for idx, s := range segStrs {
		if s != "" {
			nonEmpty = append(nonEmpty, s)
			nonEmptyIdx = append(nonEmptyIdx, idx)
		}
	}
	if len(nonEmpty) == 0 {
		return ""
	}
	if len(nonEmpty) == 1 {
		return nonEmpty[0]
	}
	var b strings.Builder
	b.WriteString(nonEmpty[0])
	for k := 1; k < len(nonEmpty); k++ {
		prevIdx := nonEmptyIdx[k-1]
		curIdx := nonEmptyIdx[k]
		total := 0
		for sIdx := prevIdx; sIdx < curIdx; sIdx++ {
			if sIdx < len(seps) {
				total += seps[sIdx]
			}
		}
		if total == 1 {
			b.WriteString("  \n")
		} else {
			b.WriteString("\n\n")
		}
		b.WriteString(nonEmpty[k])
	}
	return b.String()
}

