func containsUnpreservable(td *html.Node) bool {
	var found bool
	var dfs func(*html.Node)
	dfs = func(n *html.Node) {
		if found {
			return
		}
		for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
			if ch.Type != html.ElementNode {
				continue
			}
			tag := strings.ToLower(ch.Data)
			switch tag {
			case "h1", "h2", "h3", "h4", "h5", "h6", "ul", "ol", "blockquote", "hr", "table":
				found = true
				return
			}
			dfs(ch)
			if found {
				return
			}
		}
	}
	dfs(td)
	return found
}

